PAGES_SANS_MODE_REMISE = ['RÈGLEMENT DE LA CONSULTATION (R.C.)\n\nTravaux de restauration du bâti en pierre sèche\n\nLot unique n°01 — Pierres sèches\n\nDate et heure limites de réception des offres : le 28 août 2026 à 8h00\n', "ARTICLE 3 — CONTENU DU DOSSIER DE CONSULTATION\n\nLe dossier de consultation des entreprises (DCE) est mis à disposition des candidats sous forme électronique, gratuitement, sur le site de l'acheteur.\n", "ARTICLE 8 — CONDITIONS DE REMISE\n\nLes plis contenant les candidatures et les offres sont déposés avant la date et l'heure limites indiquées en page de garde.\n"]

def _json(obj):
    return json.dumps(obj, ensure_ascii=False, sort_keys=True)

def test_A42_reg_meme_heure_limite_sur_deux_pages_sans_conflit():
    d = app.analyser(PAGES_HEURE_DEUX_PAGES)
    fait = d['heure_limite']
    assert fait['conflit'] is False, f'A42 : 10h00 écrit en page 1 et en page 2 (même valeur) ne doit pas produire de conflit ; obtenu heure_limite = {_json(fait)}'
    assert fait['valeurs'] == [{'valeur': '10:00', 'pages': [1, 2]}], f"A42/A62 : attendu une seule valeur 10:00 sur les pages [1, 2] ; obtenu {_json(fait['valeurs'])}"

def test_A65_reg_heure_fabriquee_retiree_par_verifier():
    d = app.analyser(PAGES_HEURE_DEUX_PAGES)
    propose = copy.deepcopy(d)
    propose['heure_limite']['statut'] = 'trouvé'
    propose['heure_limite']['valeurs'] = [{'valeur': '10:00', 'pages': [1, 2]}, {'valeur': '07:00', 'pages': [2]}]
    propose['heure_limite']['conflit'] = True
    v = app.verifier(propose, PAGES_HEURE_DEUX_PAGES)
    fait = v['heure_limite']
    assert fait['valeurs'] == [{'valeur': '10:00', 'pages': [1, 2]}], f"A65 : l'heure 07:00 ne figure dans aucune page et doit être retirée ; attendu [10:00 pages [1, 2]], obtenu {_json(fait['valeurs'])}"
    assert fait['statut'] == 'trouvé' and fait['conflit'] is False, f'A65/A42 : après retrait de la valeur fabriquée, il reste une seule valeur trouvée sans conflit ; obtenu {_json(fait)}'

def test_C03_reg_validite_unique_sans_le_delai_de_recours():
    d = app.analyser(PAGES_VALIDITE_ET_RECOURS)
    fait = d['validite_offres']
    attendu = [{'valeur': {'nombre': 180, 'unite': 'jours'}, 'pages': [1]}]
    assert fait['statut'] == 'trouvé', f'C03 : statut attendu « trouvé », obtenu {_json(fait)}'
    assert fait['valeurs'] == attendu, f"C03 : le délai de deux mois d'un recours en contestation de validité n'est pas une validité des offres ; attendu {_json(attendu)}, obtenu {_json(fait['valeurs'])}"
    assert fait['conflit'] is False, f"C03 : une seule validité écrite une seule fois ne fait pas de conflit ; obtenu conflit = {fait['conflit']}"

def test_A105_reg_aucune_validite_des_offres_malgre_le_mot_validite():
    d = app.analyser(PAGES_SANS_VALIDITE)
    fait = d['validite_offres']
    assert fait == {'statut': 'non trouvé', 'valeurs': [], 'conflit': False}, f'A105 : « recours en contestation de validité » et « en cours de validité » ne fixent aucune durée de validité des offres ; attendu non trouvé, obtenu {_json(fait)}'

def test_A117_reg_electronique_du_dce_n_est_pas_un_mode_de_remise():
    d = app.analyser(PAGES_SANS_MODE_REMISE)
    fait = d['mode_remise']
    assert fait['valeurs'] == [] and fait['statut'] == 'non trouvé', f'A117/A113 : « électronique » ne qualifie que la mise à disposition du DCE et la page des plis ne nomme aucun mode ; attendu mode_remise non trouvé, obtenu {_json(fait)}'
